#include <stdio.h>
#include <string.h>

int L, C;
int eligible[6][6];
int match[36];
int visited[36];

int dfs(int cell) {
    int r = cell / C;
    int c = cell % C;
    int dr[4] = {-1, 1, 0, 0};
    int dc[4] = {0, 0, -1, 1};

    for (int k = 0; k < 4; k++) {
        int nr = r + dr[k];
        int nc = c + dc[k];

        if (nr < 0 || nr >= L || nc < 0 || nc >= C || !eligible[nr][nc])
            continue;

        int neighbor = nr * C + nc;
        if (visited[neighbor])
            continue;

        visited[neighbor] = 1;
        if (match[neighbor] == -1 || dfs(match[neighbor])) {
            match[neighbor] = cell;
            return 1;
        }
    }

    return 0;
}

int main(void) {
    int P;
    int black[6][6] = {{0}};

    if (scanf("%d %d", &L, &C) != 2)
        return 0;

    scanf("%d", &P);
    for (int i = 0; i < P; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        black[x - 1][y - 1] = 1;
    }

    int count = 0;
    for (int r = 0; r < L; r++) {
        for (int c = 0; c < C; c++) {
            if (black[r][c])
                continue;

            int dr[4] = {-1, 1, 0, 0};
            int dc[4] = {0, 0, -1, 1};
            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k];
                int nc = c + dc[k];
                if (nr >= 0 && nr < L && nc >= 0 && nc < C && black[nr][nc]) {
                    eligible[r][c] = 1;
                    count++;
                    break;
                }
            }
        }
    }

    memset(match, -1, sizeof(match));
    int matching = 0;

    for (int r = 0; r < L; r++) {
        for (int c = 0; c < C; c++) {
            if (eligible[r][c] && (r + c) % 2 == 0) {
                memset(visited, 0, sizeof(visited));
                if (dfs(r * C + c))
                    matching++;
            }
        }
    }

    printf("%d\n", count - matching);
    return 0;
}
